1	package money
2	
3	import (
4		"errors"
5		"testing"
6	)
7	
8	func TestParseMajor(t *testing.T) {
9		for _, c := range []struct {
10			in   string
11			cur  Currency
12			want int64
13		}{
14			{"12.50", USD, 1250},
15			{"12.5", USD, 1250},
16			{"7", EUR, 700},
17			{"0.99", GBP, 99},
18			{" 1000.00 ", USD, 100000},
19		} {
20			got, err := ParseMajor(c.in, c.cur)
21			if err != nil || got != c.want {
22				t.Errorf("ParseMajor(%q, %s) = %d, %v; want %d", c.in, c.cur, got, err, c.want)
23			}
24		}
25		for _, in := range []string{"", "abc", "-1", "1.", ".5", "1.234", "1,000"} {
26			if _, err := ParseMajor(in, USD); !errors.Is(err, ErrInvalidAmount) {
27				t.Errorf("ParseMajor(%q) = %v, want ErrInvalidAmount", in, err)
28			}
29		}
30		if _, err := ParseMajor("1", "XYZ"); !errors.Is(err, ErrInvalidAmount) {
31			t.Errorf("unknown currency: %v", err)
32		}
33	}
34	
35	func TestFormat(t *testing.T) {
36		for _, c := range []struct {
37			amount int64
38			cur    Currency
39			want   string
40		}{
41			{1250, USD, "$12.50"},
42			{123456789, USD, "$1,234,567.89"},
43			{-99, EUR, "-€0.99"},
44			{0, GBP, "£0.00"},
45			{100000, GBP, "£1,000.00"},
46		} {
47			if got := Format(c.amount, c.cur); got != c.want {
48				t.Errorf("Format(%d, %s) = %q, want %q", c.amount, c.cur, got, c.want)
49			}
50		}
51	}
52	
53	func TestRounding(t *testing.T) {
54		for _, c := range []struct {
55			amount int64
56			pct    int
57			want   int64
58		}{
59			{1000, 15, 150},
60			{999, 10, 100}, // 99.9
61			{995, 10, 100}, // 99.5 rounds up
62			{994, 10, 99},
63			{-995, 10, -100}, // half away from zero
64		} {
65			if got := Percent(c.amount, c.pct); got != c.want {
66				t.Errorf("Percent(%d, %d) = %d, want %d", c.amount, c.pct, got, c.want)
67			}
68		}
69		if got := BasisPoints(10000, 825); got != 825 {
70			t.Errorf("BasisPoints(10000, 825) = %d", got)
71		}
72		if got := BasisPoints(1234, 825); got != 102 { // 101.805
73			t.Errorf("BasisPoints(1234, 825) = %d", got)
74		}
75		if got := BasisPoints(200, 2500); got != 50 {
76			t.Errorf("BasisPoints(200, 2500) = %d", got)
77		}
78	}
