1	// Package jobs runs background work (renewals, webhook deliveries, emails) on a fixed number of workers.
2	package jobs
3	
4	import (
5		"context"
6		"errors"
7		"io"
8		"log/slog"
9	)
10	
11	// Job is one piece of background work.
12	type Job struct {
13		Name string
14		Run  func(ctx context.Context) error
15	}
16	
17	// ErrQueueFull is returned by Enqueue when the queue has no room.
18	var ErrQueueFull = errors.New("the job queue is full")
19	
20	// Runner runs jobs on its workers.
21	type Runner struct {
22		queue   chan Job
23		workers int
24		log     *slog.Logger
25	}
26	
27	// NewRunner returns a runner with workers workers and room for queueSize waiting jobs. A nil log discards.
28	func NewRunner(workers, queueSize int, log *slog.Logger) *Runner {
29		if workers < 1 {
30			workers = 1
31		}
32		if log == nil {
33			log = slog.New(slog.NewTextHandler(io.Discard, nil))
34		}
35		return &Runner{queue: make(chan Job, queueSize), workers: workers, log: log}
36	}
37	
38	// Start starts the workers.
39	func (r *Runner) Start() {
40		for i := 0; i < r.workers; i++ {
41			go r.work()
42		}
43	}
44	
45	func (r *Runner) work() {
46		for j := range r.queue {
47			if err := j.Run(context.Background()); err != nil {
48				r.log.Error("job failed", "job", j.Name, "err", err)
49			}
50		}
51	}
52	
53	// Enqueue adds a job to the queue without waiting. It returns ErrQueueFull when the queue has no room.
54	func (r *Runner) Enqueue(j Job) error {
55		select {
56		case r.queue <- j:
57			return nil
58		default:
59			return ErrQueueFull
60		}
61	}
62	
63	// Stop stops the runner.
64	func (r *Runner) Stop() {
65		close(r.queue)
66	}
67

