47	// minor units. It accepts at most the currency's MinorUnits decimals and pads fewer.
48	func ParseMajor(s string, c Currency) (int64, error) {
49		if !c.Valid() {
50			return 0, fmt.Errorf("%w: unknown currency %q", ErrInvalidAmount, c)
51		}
52		digits := c.MinorUnits()
53		s = strings.TrimSpace(s)
54		whole, frac, hasDot := strings.Cut(s, ".")
55		if whole == "" || (hasDot && frac == "") || len(frac) > digits {
56			return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
57		}
58		for _, r := range whole + frac {
59			if r < '0' || r > '9' {
60				return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
61			}
62		}
63		for len(frac) < digits {
64			frac += "0"
65		}
66		n, err := strconv.ParseInt(whole+frac, 10, 64)
67		if err != nil {
68			return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
69		}
70		return n, nil
71	}
