86	// split breaks an amount into its sign, its whole major units and its decimal part (".50", or "" when c has no decimals).
87	func split(amount int64, c Currency) (sign string, whole int64, frac string) {
88		if amount < 0 {
89			sign, amount = "-", -amount
90		}
