116	// Percent returns pct percent of amount, rounded half away from zero to a whole minor unit.
117	func Percent(amount int64, pct int) int64 { return divRound(amount*int64(pct), 100) }
118	
119	// BasisPoints returns bp basis points (hundredths of a percent) of amount, rounded half away from zero.
120	func BasisPoints(amount int64, bp int) int64 { return divRound(amount*int64(bp), 10000) }
