122	// divRound divides and rounds half away from zero.
123	func divRound(num, den int64) int64 {
124		if (num < 0) != (den < 0) {
125			return -((abs(num) + abs(den)/2) / abs(den))
126		}
127		return (abs(num) + abs(den)/2) / abs(den)
128	}
129	
130	func abs(v int64) int64 {
131		if v < 0 {
132			return -v
133		}
134		return v
135	}
