12	// planView is a plan with its price in major units with the currency's decimals ("12.50", "1000" for JPY) and formatted for
13	// people ("$12.50").
14	type planView struct {
15		store.Plan
16		Price          string `json:"price"`
17		PriceFormatted string `json:"price_formatted"`
18	}
19	
20	func viewPlan(p store.Plan) planView {
21		return planView{Plan: p, Price: money.FormatMajor(p.UnitAmount, p.Currency), PriceFormatted: money.Format(p.UnitAmount, p.Currency)}
22	}
23	
24	func (s *Server) listPlans(w http.ResponseWriter, r *http.Request, p auth.Principal) {
25		items := []planView{}
26		for _, pl := range s.store.Plans(p.OrgID) {
27			items = append(items, viewPlan(pl))
28		}
29		writeJSON(w, http.StatusOK, list{Items: items})
30	}
31	
32	// createPlan takes the price in major units, as a string ("12.50"), the way people type it.
33	func (s *Server) createPlan(w http.ResponseWriter, r *http.Request, p auth.Principal) {
34		var in struct {
35			Name      string          `json:"name"`
36			Currency  money.Currency  `json:"currency"`
37			Price     string          `json:"price"`
38			Interval  store.Interval  `json:"interval"`
39			UsageType store.UsageType `json:"usage_type"`
40			TrialDays int             `json:"trial_days"`
41		}
42		if !decode(w, r, &in) {
43			return
44		}
45		amount, err := money.ParseMajor(in.Price, in.Currency)
46		if err != nil {
47			if errors.Is(err, money.ErrInvalidAmount) {
48				writeError(w, http.StatusUnprocessableEntity, "invalid_amount", err.Error())
49				return
50			}
51			s.storeError(w, err)
52			return
53		}
54		pl, err := s.store.CreatePlan(store.Plan{OrgID: p.OrgID, Name: in.Name, Currency: in.Currency, UnitAmount: amount, Interval: in.Interval,
55			UsageType: in.UsageType, TrialDays: in.TrialDays}, s.clock.Now())
56		if err != nil {
57			s.storeError(w, err)
58			return
59		}
60		writeJSON(w, http.StatusCreated, viewPlan(pl))
